    10→import { UserImage } from "shared/components";
    11→import { Colors } from "shared/styles";
    12→import { MessageContentListItem } from "../message-content-item-list";
    13→
    14→export const MessageContentBottomSheet: React.FC = () => {
    15→  const ref = useRef<BottomSheetModal>(null);
    16→  const fadeIn = useRef(
    17→    animateSequence(
    18→      { opacity: [0, 1] },
    19→      {
    20→        duration: 200,
    21→      },
    22→    ),
    23→  ).current;
    24→  const [payload, setPayload] = useAtom(TimelineAtoms.longPressPayload);
    25→  const avatarUrl = useMemo(() => {
    26→    return payload?.event.senderProfile.tag === ProfileDetails_Tags.Ready
    27→      ? payload?.event.senderProfile.inner.avatarUrl
    28→      : null;
    29→  }, [payload]);
    30→  const displayName = useMemo(() => {
    31→    return payload?.event.senderProfile.tag === ProfileDetails_Tags.Ready
    32→      ? payload?.event.senderProfile.inner.displayName
    33→      : undefined;
    34→  }, [payload]);
    35→  const setReplyPayload = useSetAtom(TimelineAtoms.replyPayload);
    36→
    37→  const handleBottomSheetClose = useCallback(() => {
    38→    fadeIn.reverse(() => {
    39→      setPayload(null);
    40→    });
    41→  }, [fadeIn, setPayload]);
    42→
    43→  const handleReply = useCallback(() => {
    44→    if (!payload) return;
    45→    const eventId = getEventId(payload.event);
    46→    if (!eventId) return;
    47→
    48→    setReplyPayload({
    49→      eventId,
    50→      senderName: displayName ?? payload.event.sender,
    51→      content: payload.content,
    52→    });
    53→
    54→    ref.current?.dismiss();
    55→  }, [payload, displayName, setReplyPayload]);
    56→
    57→  const handleForward = useCallback(() => {}, [payload]);
    58→
    59→  const list = [
    60→    {
    61→      title: "Reply",
    62→      icon: require("assets/icons/reply.png"),
    63→      onPress: handleReply,
    64→    },
    65→    {
    66→      title: "Forward",
    67→      icon: require("assets/icons/forward.png"),
    68→      onPress: handleForward,
    69→    },
    70→  ];
    71→
    72→  useEffect(() => {
    73→    if (!payload) return;
    74→
    75→    fadeIn.start();
    76→    ref.current?.present();
    77→  }, [payload, fadeIn]);
    78→
    79→  if (!payload) return null;
    80→
    81→  return (
    82→    <Block
    83→      absolute
    84→      width="100%"
    85→      height="100%"
    86→      offsets={{ left: 0, bottom: 0 }}
    87→      animations={fadeIn.animations}
    88→      zIndex={9999}
    89→      background={Colors.black70}
    90→    >
    91→      <BottomSheetModal
    92→        ref={ref}
    93→        handleStyle={styles.handle}
    94→        handleIndicatorStyle={styles.handleIndicator}
    95→        backgroundStyle={styles.background}
    96→        enablePanDownToClose
    97→        enableDynamicSizing
    98→        onDismiss={handleBottomSheetClose}
    99→      >
   100→        <BottomSheetView>
   101→          <Block
   102→            paddings={{
   103→              paddingHorizontal: 20,
   104→              paddingBottom: 20,
   105→            }}
   106→            gap={16}
   107→            align="center"
   108→          >
   109→            <Block
   110→              width="100%"
   111→              flexDirection="row"
   112→              gap={16}
   113→              align="center"
   114→              justify="space-between"
   115→              margins={{ marginBottom: 32 }}
   116→            >
   117→              <Block flexDirection="row" gap={16} align="center" flex={1}>
   118→                <UserImage
   119→                  avatarUrl={avatarUrl}
   120→                  displayName={displayName}
   121→                  height={40}
   122→                  width={40}
   123→                />
   124→                <Block>
   125→                  <Text color={Colors.primary}>{displayName}</Text>
   126→                  <Text numberOfLines={3} flex={1}>
   127→                    {payload.content}
   128→                  </Text>
   129→                </Block>
   130→              </Block>
   131→              <Text color={Colors.white50}>
   132→                {format(Number(payload.event.timestamp), "HH:mm")}
   133→              </Text>
   134→            </Block>
   135→            <Block width="100%">
   136→              {list.map((item) => (
   137→                <MessageContentListItem key={item.title} {...item} />
   138→              ))}
   139→            </Block>
   140→          </Block>
   141→        </BottomSheetView>
   142→      </BottomSheetModal>
   143→    </Block>
   144→  );
   145→};
   146→
   147→const styles = StyleSheet.create({
   148→  background: {
   149→    backgroundColor: Colors.blackMinus1,
   150→    borderTopLeftRadius: 24,
   151→    borderTopRightRadius: 24,
   152→  },
   153→  handle: {
   154→    borderWidth: 1,
   155→    borderBottomWidth: 0,
   156→    borderTopLeftRadius: 24,
   157→    borderTopRightRadius: 24,
   158→    paddingHorizontal: 12,
   159→    paddingTop: 12,
   160→    paddingBottom: 24,
   161→  },
   162→  handleIndicator: {
   163→    width: 84,
   164→    height: 4,
   165→    backgroundColor: Colors.white50,
   166→  },
   167→});
