    70→export class MatrixService {
    71→  //TODO: change every method that uses MatrixService.instance to a class method
    72→  public static instance: ClientInterface | null;
    73→  public static syncService: SyncServiceInterface | null;
    74→  private static verificationController: SessionVerificationControllerInterface | null =
    75→    null;
