   340→  /** Manually refresh the room list and update the atom */
   341→  public static refreshRoomList = async () => {
   342→    if (!this.instance) return;
   343→
   344→    try {
   345→      const roomsArray = this.getRooms();
   346→
   347→      const sortedRooms = await Promise.all(
   348→        roomsArray.map(async (room) => ({
   349→          room,
   350→          timestamp: (await room.latestEvent())?.timestamp || 0,
   351→        })),
   352→      );
   353→
   354→      const filteredAndSortedRooms = sortedRooms
   355→        .filter(({ room }) => {
   356→          const membership = room.membership();
   357→
   358→          return (
   359→            membership !== Membership.Banned &&
   360→            membership !== Membership.Left &&
   361→            membership !== Membership.Knocked
   362→          );
   363→        })
   364→        .sort((a, b) => {
   365→          const aInvited = a.room.membership() === Membership.Invited ? 1 : 0;
   366→          const bInvited = b.room.membership() === Membership.Invited ? 1 : 0;
   367→          if (aInvited !== bInvited) return bInvited - aInvited;
   368→
   369→          return Number(b.timestamp) - Number(a.timestamp);
   370→        });
   371→
   372→      MatrixJotaiStore.set(
   373→        MatrixAtoms.roomList,
   374→        filteredAndSortedRooms.map(({ room }) => room),
   375→      );
   376→    } catch (error) {
   377→      console.error("Failed to refresh room list:", error);
   378→    }
   379→  };
