   385→    password,
   386→  }: LoginWithUsernameAndPasswordData) => {
   387→    if (!this.instance) throw new Error("Failed to initialize client");
   388→    await this.instance.login(username, password, undefined, undefined);
   389→    const session = this.instance.session();
   390→    console.log(
   391→      this.instance.encryption().verificationState(),
   392→      "verificationState",
   393→    );
   394→
   395→    // After login, we need to recreate the client with sliding sync configured
