   642→  public static getReadReceipts = async (event: EventTimelineItem) => {
   643→    const userIds = Array.from(event.readReceipts.keys()).map(
   644→      (userIds) => userIds,
   645→    );
   646→
   647→    // Don't show read receipts for the sender's own message
   648→    const filteredUserIds = userIds.filter((userId) => userId !== event.sender);
   649→
   650→    if (!filteredUserIds.length) {
   651→      return [];
   652→    }
   653→
   654→    try {
   655→      const profilePromises = filteredUserIds.map((userId) =>
   656→        this.instance?.getProfile(userId),
   657→      );
   658→      const profiles = await Promise.allSettled(profilePromises);
   659→      return profiles
   660→        .filter((p) => p.status === "fulfilled")
   661→        .map((p) => p.value)
   662→        .filter((p) => p !== undefined);
   663→    } catch (error) {
   664→      console.error("Failed to get read receipt users:", error);
   665→      return [];
   666→    }
   667→  };
