   939→    callback: (state: MappedBackupState) => void,
   940→  ): TaskHandleInterface => {
   941→    if (!this.instance) throw new Error("Client not initialized");
   942→    return this.instance.encryption().backupStateListener({
   943→      onUpdate: async (state: BackupState) => {
   944→        if (state === BackupState.Unknown) {
   945→          if (!this.instance) throw new Error("Client not initialized");
   946→          const backupExists = await this.instance
   947→            .encryption()
   948→            .backupExistsOnServer();
   949→
   950→          if (backupExists) callback("enabled");
   951→          else callback("unknown");
   952→          return;
   953→        }
   954→        callback(mapBackupState(state));
   955→      },
   956→    });
   957→  };
