    11→import { OtherMessage } from "../other-message/OtherMessage";
    12→import { ProfileInfoMessage } from "../profile-info-message";
    13→import { RoomInfoMessage } from "../room-info-message";
    14→import { TextMessage } from "../text-message";
    15→import { UnableToDecryptMessage } from "../unable-to-decrypt-message";
    16→import { VideoMessage } from "../video-message";
    17→import { VoiceMessage } from "../voice-message";
    18→
    19→interface Props {
    20→  event: EventTimelineItem;
    21→  isPreviousSameSender: boolean;
    22→}
    23→
    24→const getEventType = (event: EventTimelineItem) => {
    25→  if (
    26→    event.content.tag === TimelineItemContent_Tags.RtcNotification ||
    27→    event.content.tag === TimelineItemContent_Tags.CallInvite
    28→  ) {
    29→    return "call";
    30→  }
    31→  if (event.content.tag === TimelineItemContent_Tags.State) {
    32→    const stateContent = event.content.inner.content;
    33→    // This was used to handle call events in older versions of the SDK. Might be useful in the future.
    34→    // if (
    35→    //   stateContent.tag === OtherState_Tags.Custom &&
    36→    //   stateContent.inner?.eventType === "org.matrix.msc3401.call.member"
    37→    // ) {
    38→    //   return "call";
    39→    // }
    40→
    41→    if (stateContent.tag.includes("Room")) return "room";
    42→  }
    43→
    44→  if (event.content.tag === TimelineItemContent_Tags.MsgLike) {
    45→    const kind = event.content.inner.content.kind;
    46→    if (kind?.tag === MsgLikeKind_Tags.Message) {
    47→      const msgType = kind.inner.content.msgType;
    48→
    49→      if (msgType?.tag === MessageType_Tags.Text) {
    50→        return "text";
    51→      } else if (msgType?.tag === MessageType_Tags.Image) {
    52→        return "image";
    53→      } else if (msgType?.tag === MessageType_Tags.File) {
    54→        return "file";
    55→      } else if (msgType?.tag === MessageType_Tags.Video) {
    56→        return "video";
    57→      } else if (msgType?.tag === MessageType_Tags.Audio) {
    58→        return "audio";
    59→      } else if (msgType?.tag === MessageType_Tags.Other) {
    60→        return "other";
    61→      } else {
    62→        return "unkown";
    63→      }
    64→    }
    65→
    66→    if (kind?.tag === MsgLikeKind_Tags.UnableToDecrypt) {
    67→      return "unableToDecrypt";
    68→    }
    69→  }
    70→  if (event.content.tag === TimelineItemContent_Tags.RoomMembership) {
    71→    return "membership";
    72→  }
    73→  if (event.content.tag === TimelineItemContent_Tags.ProfileChange) {
    74→    return "profile";
    75→  }
    76→  return "unkown";
    77→};
    78→
    79→export const SingleMessageType: FC<Props> = ({
    80→  event,
    81→  isPreviousSameSender,
    82→}) => {
    83→  if (!event) return null;
    84→
    85→  switch (getEventType(event)) {
    86→    case "text": {
    87→      return (
    88→        <TextMessage
    89→          event={event}
    90→          isPreviousSameSender={isPreviousSameSender}
    91→        />
    92→      );
    93→    }
    94→    case "image": {
    95→      return (
    96→        <ImageMessage
    97→          event={event}
    98→          isPreviousSameSender={isPreviousSameSender}
    99→        />
   100→      );
   101→    }
   102→    case "audio": {
   103→      return (
   104→        <VoiceMessage
   105→          event={event}
   106→          isPreviousSameSender={isPreviousSameSender}
   107→        />
   108→      );
   109→    }
   110→    case "video": {
   111→      return (
   112→        <VideoMessage
   113→          event={event}
   114→          isPreviousSameSender={isPreviousSameSender}
   115→        />
   116→      );
   117→    }
   118→    case "other": {
   119→      return <OtherMessage event={event} />;
   120→    }
   121→    case "call": {
   122→      return (
   123→        <CallMessage
   124→          event={event}
   125→          isPreviousSameSender={isPreviousSameSender}
   126→        />
   127→      );
   128→    }
   129→    case "membership": {
   130→      return <MembershipInfoMessage event={event} />;
   131→    }
   132→    case "profile": {
   133→      return <ProfileInfoMessage event={event} />;
   134→    }
   135→    case "room": {
   136→      return <RoomInfoMessage event={event} />;
   137→    }
   138→    case "unableToDecrypt": {
   139→      return <UnableToDecryptMessage event={event} />;
   140→    }
   141→    default:
   142→      return null;
   143→  }
   144→};
