     1→import { Block, useAnimateParallel } from "@prototyp/skeletor";
     2→import type { EventTimelineItem } from "@unomed/react-native-matrix-sdk";
     3→import { useSetAtom } from "jotai";
     4→import { TimelineAtoms } from "modules/timeline";
     5→import { type ReactNode, useCallback } from "react";
     6→import { Vibration } from "react-native";
     7→import { Gesture, GestureDetector } from "react-native-gesture-handler";
     8→import { Easing, runOnJS } from "react-native-reanimated";
     9→
    10→interface Props {
    11→  children: ReactNode;
    12→  event: EventTimelineItem;
    13→  content: string;
    14→  onStart?: () => void;
    15→  onFinalize?: () => void;
    16→}
    17→
    18→export const MessageLongPressWrapper: React.FC<Props> = ({
    19→  children,
    20→  event,
    21→  content,
    22→  onStart,
    23→  onFinalize,
    24→}) => {
    25→  const scale = useAnimateParallel(
    26→    { scaleX: [1, 1.1], scaleY: [1, 1.1] },
    27→    { duration: 700, easing: Easing.bezierFn(0.31, 0.04, 0.03, 1.04) },
    28→  );
    29→  const setLongPressPayload = useSetAtom(TimelineAtoms.longPressPayload);
    30→
    31→  const openSheet = useCallback(() => {
    32→    setLongPressPayload({ event, content });
    33→  }, [content, event, setLongPressPayload]);
    34→
    35→  const vibrateEnd = useCallback(() => {
    36→    Vibration.vibrate(1);
    37→  }, []);
    38→
    39→  const longPress = Gesture.LongPress()
    40→    .minDuration(500)
    41→    .onBegin(() => {
    42→      runOnJS(scale.start)();
    43→      if (!onStart) return;
    44→      runOnJS(onStart)();
    45→    })
    46→    .onStart(() => {
    47→      runOnJS(openSheet)();
    48→      runOnJS(vibrateEnd)();
    49→    })
    50→    .onTouchesCancelled(() => {
    51→      runOnJS(scale.reverse)();
    52→    })
    53→    .onFinalize((_, success) => {
    54→      runOnJS(scale.reverse)();
    55→      if (onFinalize && !success) {
    56→        runOnJS(onFinalize)();
    57→      }
    58→    });
    59→
    60→  if (!event.canBeRepliedTo) return <>{children}</>;
    61→
    62→  return (
    63→    <>
    64→      <GestureDetector gesture={longPress}>
    65→        <Block animations={scale.animations}>{children}</Block>
    66→      </GestureDetector>
    67→    </>
    68→  );
    69→};
